async function importProduct(params: {
  source: DraftProduct;
  categoryId: string;
  categoryName: string;
  kind: ProductKind;
}): Promise<ImportResult> {
  const title = params.source.title?.trim();

  if (!title) {
    throw new Error(`${params.source.externalId}: отсутствует title`);
  }

  const description = normalizeDescription(params.source.rawText);

  if (!description) {
    throw new Error(`${params.source.externalId}: отсутствует rawText`);
  }

  const price = extractBasePrice(params.source.rawText);
  const slug = getProductSlug(params.source);

  const preparedImages = await prepareImages({
    product: params.source,
  });

  await mkdir(UPLOADS_DIR, {
    recursive: true,
  });

  for (const image of preparedImages) {
    await copyFile(image.sourcePath, image.destinationPath);
  }

  const existingProduct = await prisma.product.findFirst({
    where: {
      slug,
    },
  });

  const product = existingProduct
    ? await prisma.product.update({
        where: {
          id: existingProduct.id,
        },
        data: {
          categoryId: params.categoryId,
          title,
          slug,
          description,
          price,
          additions: getProductAdditions(params.kind),
          isActive: true,
          deletedAt: null,
        },
      })
    : await prisma.product.create({
        data: {
          categoryId: params.categoryId,
          title,
          slug,
          description,
          price,
          additions: getProductAdditions(params.kind),
          isActive: true,
        },
      });


  const results: ImportResult[] = [];

  for (const [index, classified] of classifiedProducts.entries()) {
    const category = categoryByKind[classified.kind];

    const result = await importProduct({
      source: classified.product,
      kind: classified.kind,
      categoryId: category.id,
      categoryName: category.name,
    });

    results.push(result);

    console.log(
      `[${String(index + 1).padStart(2, '0')}/${classifiedProducts.length}] ` +
        `${result.action === 'created' ? 'создан' : 'обновлён'}: ` +
        `${result.title} | ` +
        `${result.price.toLocaleString('ru-RU')} ₽ | ` +
        `${result.categoryName} | ` +
        `фото: ${result.imagesCount}`,
    );
  }

  const createdCount = results.filter(
    (result) => result.action === 'created',
  ).length;

  const updatedCount = results.filter(
    (result) => result.action === 'updated',
  ).length;

  const imagesCount = results.reduce(
    (total, result) => total + result.imagesCount,
    0,
  );

  console.log('');
