let products = JSON.parse(load("clean_products_json"));
const labels = [
  ['размер', 'Размер'], ['каркас', 'Каркас'],
  ['внутренняя отделка', 'Внутренняя отделка'],
  ['наружная отделка', 'Наружная отделка'], ['утеплитель', 'Утеплитель'],
  ['кровля', 'Кровля'], ['сетка', 'Сетка'], ['комплектация', 'Комплектация'],
  ['окно', 'Окно'], ['крыша', 'Крыша'], ['цена', 'Цена'],
  ['стоимость', 'Стоимость'], ['местоположение', 'Местоположение']
];
function cleanDescription(input) {
  let d = input
    .replace(/утепленный/giu, 'утеплённый')
    .replace(/осп/giu, 'ОСП')
    .replace(/\s+:/g, ':')
    .replace(/\s{2,}/g, ' ');
  for (const [raw, canonical] of labels) {
    d = d.replace(new RegExp(`(^|[.!?]\\\\s+)${raw}\\\\s*:\\\\s*`, 'giu'), (_m,prefix) => `${prefix}${canonical}: `);
  }
  d = d
    .replace(/Цена:\s*([\d ]+)\s*₽\s*\.?\s*(утеплённый|зимний|летний)/giu, (_m, amount, variant) => `Цена (${variant.toLowerCase()}): ${amount.trim()} ₽`)
    .replace(/Цена:\s*([\d ]+)\s*₽\s*(утеплённый|зимний|летний)/giu, (_m, amount, variant) => `Цена (${variant.toLowerCase()}): ${amount.trim()} ₽`)
    .replace(/Цена:\s*([\d ]+)\s*₽\s*\.?\s*Цена\s*\(([^)]+)\)/giu, (_m, amount, variant) => `Цена: ${amount.trim()} ₽. Цена (${variant})`)
    .replace(/бруса\s+(\d+)\s*×\s*(\d+)(?!\s*(?:мм|см))/giu, 'бруса $1 × $2 мм')
    .replace(/ячейка\s+(\d+)\s*×\s*(\d+)(?!\s*(?:мм|см))/giu, 'ячейка $1 × $2 мм')
    .replace(/Окно:\s*300\s*×\s*400(?!\s*(?:мм|см))/giu, 'Окно: 30 × 40 см')
    .replace(/\s+\./g, '.')
    .replace(/\.(?=[А-ЯЁ])/gu, '. ')
    .replace(/\s{2,}/g, ' ')
    .trim();
  return /[.!?]$/u.test(d) ? d : d + '.';
}
