  configuration.forEach((addition) => {
    const selected = selectedById.get(addition.id);
    if (!selected) {
      if (addition.required) {
        fail(
          'selectedAdditions',
          `is missing required addition "${addition.title}". Product parameters may have changed.`,
        );
