      );
    }
    if (addition.type === 'boolean' && selected.type === 'boolean') {
      snapshot.push({
        additionId: addition.id,
        type: addition.type,
        title: addition.title,
        value: selected.value,
        unitPrice: addition.price,
        totalPrice: selected.value ? addition.price : 0,
