import type {
  ProductAddition,
  SelectedProductAddition,
} from '@/entities/product';
import { formatPrice } from '@/shared/utils/format-price';

type Props = {
  additions: ProductAddition[];
  selected: SelectedProductAddition[];
  errors: Record<string, string>;
  onChange: (value: SelectedProductAddition[]) => void;
};

export function ProductAdditionsSelector({
  additions,
  selected,
  errors,
  onChange,
}: Props) {
  const selectedById = new Map(selected.map((item) => [item.additionId, item]));

  function setSelection(next: SelectedProductAddition) {
    onChange([
      ...selected.filter((item) => item.additionId !== next.additionId),
      next,
    ]);
  }

  if (!additions.length) return null;

  return (
    <section className="space-y-3 rounded-xl border border-border p-4">
      <h2 className="font-medium">Дополнения</h2>
      {additions.map((addition) => {
        const selection = selectedById.get(addition.id);
        return (
          <div key={addition.id} className="space-y-2 border-t border-border pt-3 first:border-0 first:pt-0">
            <div className="flex justify-between gap-3 text-sm">
              <span>{addition.title}{addition.required ? ' *' : ''}</span>
              <span className="text-muted-foreground">
                {addition.type === 'boolean'
                  ? `+${formatPrice(addition.price)}`
                  : `${formatPrice(addition.price)}/${addition.unitLabel}`}
              </span>
            </div>
            {addition.type === 'boolean' ? (
              <div className="flex gap-2">
                {[true, false].map((value) => (
                  <button key={String(value)} type="button"
                    className={`rounded-md border px-4 py-2 text-sm ${
                      selection?.type === 'boolean' && selection.value === value
                        ? 'border-primary bg-primary text-primary-foreground'
                        : 'border-border'
                    }`}
                    onClick={() => setSelection({
                      additionId: addition.id,
                      type: 'boolean',
                      value,
                    })}>
                    {value ? 'Да' : 'Нет'}
                  </button>
                ))}
              </div>
            ) : (
              <input type="number" step={1} min={addition.min}
                max={addition.max ?? undefined}
                className="w-32 rounded-md border border-input bg-background px-3 py-2"
                value={selection?.type === 'quantity' ? selection.value : ''}
                onChange={(event) => {
                  if (event.target.value === '') {
                    onChange(selected.filter((item) => item.additionId !== addition.id));
                    return;
                  }
                  setSelection({
                    additionId: addition.id,
                    type: 'quantity',
                    value: Number(event.target.value),
                  });
                }} />
            )}
            {errors[addition.id] && (
              <p className="text-xs text-destructive">{errors[addition.id]}</p>
            )}
          </div>
        );
      })}
    </section>
  );
}
import * as React from 'react';
import { Slot } from 'radix-ui';
import { cva, type VariantProps } from 'class-variance-authority';

import { cn } from '@/shared/utils/cn';

const buttonVariants = cva(
  "group/button inline-flex cursor-pointer shrink-0 items-center justify-center rounded-lg border border-transparent bg-clip-padding text-sm font-medium whitespace-nowrap transition-all outline-none select-none focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: 'bg-primary text-primary-foreground hover:bg-primary/80',
        outline:
          'border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50',
        secondary:
          'bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground',
        ghost:
          'hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50',
        warning:
          'bg-amber-500/10 text-amber-700 hover:bg-amber-500/20 focus-visible:border-amber-500/40 focus-visible:ring-amber-500/20 dark:bg-amber-500/15 dark:text-amber-300 dark:hover:bg-amber-500/25 dark:focus-visible:ring-amber-500/35',
        destructive:
          'bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40',
        link: 'text-primary underline-offset-4 hover:underline',
      },
      size: {
        default:
          'h-8 gap-1.5 px-4 has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3',
        xs: 'h-6 gap-1 rounded-[min(var(--radius-md),10px)] px-3 text-xs in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-2.5 has-data-[icon=inline-start]:pl-2.5 [&_svg:not([class*=\'size-\'])]:size-3',
        sm: 'h-7 gap-1 rounded-[min(var(--radius-md),12px)] px-3.5 text-[0.8rem] in-data-[slot=button-group]:rounded-lg has-data-[icon=inline-end]:pr-3 has-data-[icon=inline-start]:pl-3 [&_svg:not([class*=\'size-\'])]:size-3.5',
        lg: 'h-9 gap-1.5 px-5 has-data-[icon=inline-end]:pr-4 has-data-[icon=inline-start]:pl-4',
        icon: 'size-8',
        'icon-xs':
          'size-6 rounded-[min(var(--radius-md),10px)] in-data-[slot=button-group]:rounded-lg [&_svg:not([class*=\'size-\'])]:size-3',
        'icon-sm':
          'size-7 rounded-[min(var(--radius-md),12px)] in-data-[slot=button-group]:rounded-lg',
        'icon-lg': 'size-9',
      },
    },
    defaultVariants: {
      variant: 'default',
      size: 'default',
    },
  },
);

function Button({
  className,
  variant = 'default',
  size = 'default',
  asChild = false,
  ...props
}: React.ComponentProps<'button'> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean;
  }) {
  const Component = asChild ? Slot.Root : 'button';

  return (
    <Component
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, buttonVariants };

