import { Minus, Plus } from 'lucide-react';

import { useCartStore } from '@/entities/cart';
import { cn } from '@/shared/utils/cn';

export type ProductQuantityCounterVariant = 'card' | 'details';

type ProductQuantityCounterProps = {
  productId: string;
  variant?: ProductQuantityCounterVariant;
};

export function getProductActionHeightClass(
  variant: ProductQuantityCounterVariant,
) {
  return variant === 'details' ? 'h-9' : 'h-8';
}

export function ProductQuantityCounter({
  productId,
  variant = 'card',
}: ProductQuantityCounterProps) {
  const quantity = useCartStore((state) => state.getItemQuantity(productId));
  const increaseItem = useCartStore((state) => state.increaseItem);
  const decreaseItem = useCartStore((state) => state.decreaseItem);

  return (
    <div
      className={cn(
        'grid grid-cols-[2.25rem_1fr_2.25rem] overflow-hidden rounded-lg border border-border bg-background',
        getProductActionHeightClass(variant),
      )}
    >
      <button
        type="button"
        className="flex h-full items-center justify-center transition-colors hover:bg-muted"
        onClick={() => decreaseItem(productId)}
      >
        <Minus className="size-4" />
      </button>

      <div className="flex items-center justify-center text-sm font-medium">
        {quantity}
      </div>

      <button
        type="button"
        className="flex h-full items-center justify-center transition-colors hover:bg-muted"
        onClick={() => increaseItem(productId)}
      >
        <Plus className="size-4" />
      </button>
    </div>
  );
}import { Button } from '@/components/ui/Button';
import type { Ad } from '@/entities/ad';
import { useCartStore } from '@/entities/cart';
import type { Product, SelectedProductAddition } from '@/entities/product';
import { createCartConfigurationKey } from '@/entities/product/lib/product-additions';
import { cn } from '@/shared/utils/cn';
import {
  ProductQuantityCounter,
  getProductActionHeightClass,
  type ProductQuantityCounterVariant,
} from '@/widgets/ProductQuantityCounter';

type AddToCartButtonProps = {
  variant?: ProductQuantityCounterVariant;
  selectedAdditions?: SelectedProductAddition[];
  isConfigurationValid?: boolean;
  onInvalidConfiguration?: () => void;
} & (
    | { itemType: 'product'; item: Product }
    | { itemType: 'ad'; item: Ad }
  );

export function AddToCartButton({
  variant = 'card',
  itemType,
  item,
  selectedAdditions = [],
  isConfigurationValid = true,
  onInvalidConfiguration,
}: AddToCartButtonProps) {
  const configurationKey =
    itemType === 'product'
      ? createCartConfigurationKey(item.id, selectedAdditions)
      : item.id;
  const quantity = useCartStore((state) =>
    state.items.find((cartItem) =>
      (cartItem.configurationKey ?? cartItem.product.id) === configurationKey,
    )?.quantity ?? 0,
  );
  const addItem = useCartStore((state) => state.addItem);
  const adItems = useCartStore((state) => state.adItems);
  const addAdItem = useCartStore((state) => state.addAdItem);
  const removeAdItem = useCartStore((state) => state.removeAdItem);

  if (itemType === 'ad') {
    const isInCart = adItems.some((i) => i.ad.id === item.id);

    return (
      <Button
        type="button"
        variant={isInCart ? 'outline' : 'default'}
        size={variant === 'details' ? 'lg' : 'default'}
        className={cn('w-full', getProductActionHeightClass(variant))}
        onClick={() => (isInCart ? removeAdItem(item.id) : addAdItem(item))}
      >
        {isInCart ? 'Убрать из корзины' : 'В корзину'}
      </Button>
    );
  }

  if (quantity > 0) {
    return (
      <ProductQuantityCounter
        productId={configurationKey}
        variant={variant}
      />
    );
  }

  return (
    <Button
      type="button"
      variant="outline"
      size={variant === 'details' ? 'lg' : 'default'}
      className={cn('w-full', getProductActionHeightClass(variant))}
      onClick={() => {
        if (!isConfigurationValid) {
          onInvalidConfiguration?.();
          return;
        }
        addItem(item, selectedAdditions);
      }}
    >
      В корзину
    </Button>
  );
}
