import { create } from 'zustand';
import { createJSONStorage, persist } from 'zustand/middleware';

import type { Ad } from '@/entities/ad';
import type { Product, SelectedProductAddition } from '@/entities/product';
import {
  calculateProductAdditionsTotal,
  createCartConfigurationKey,
} from '@/entities/product/lib/product-additions';

export type CartStoreItem = {
  product: Product;
  quantity: number;
  selectedAdditions: SelectedProductAddition[];
  configurationKey: string;
  configuredUnitPrice: number;
};

export type CartAdItem = {
  ad: Ad;
};

type CartStore = {
  items: CartStoreItem[];
  adItems: CartAdItem[];
  addItem: (product: Product, selectedAdditions?: SelectedProductAddition[]) => void;
  removeItem: (configurationKey: string) => void;
  increaseItem: (configurationKey: string) => void;
  decreaseItem: (configurationKey: string) => void;
  setItemQuantity: (configurationKey: string, quantity: number) => void;
  clearCart: () => void;
  clearAdItems: () => void;
  getItemQuantity: (productId: string) => number;
  getTotalItems: () => number;
  getTotalAmount: () => number;
  getTotalAdItems: () => number;
  getTotalAdAmount: () => number;
  addAdItem: (ad: Ad) => void;
  removeAdItem: (adId: string) => void;
  hasAdItem: (adId: string) => boolean;
};

export const useCartStore = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],
      adItems: [],

      addAdItem: (ad) => {
        if (get().hasAdItem(ad.id)) return;
        set((state) => ({ adItems: [...state.adItems, { ad }] }));
      },

      removeAdItem: (adId) => {
        set((state) => ({
          adItems: state.adItems.filter((i) => i.ad.id !== adId),
        }));
      },

      hasAdItem: (adId) => {
        return get().adItems.some((i) => i.ad.id === adId);
      },

      addItem: (product, selectedAdditions = []) => {
        const configurationKey = createCartConfigurationKey(
          product.id,
          selectedAdditions,
        );
        const currentItem = get().items.find(
          (item) => item.configurationKey === configurationKey,
        );

        if (currentItem) {
          get().increaseItem(configurationKey);
          return;
        }

        set((state) => ({
          items: [
            ...state.items,
            {
              product,
              quantity: 1,
              selectedAdditions,
              configurationKey,
              configuredUnitPrice:
                product.price +
                calculateProductAdditionsTotal(
                  product.additions ?? [],
                  selectedAdditions,
                ),
            },
          ],
        }));
      },

      removeItem: (configurationKey) => {
        set((state) => ({
          items: state.items.filter(
            (item) => item.configurationKey !== configurationKey,
          ),
        }));
      },

      increaseItem: (configurationKey) => {
        set((state) => ({
          items: state.items.map((item) =>
            (item.configurationKey ?? item.product.id) === configurationKey ||
            item.product.id === configurationKey
              ? { ...item, quantity: item.quantity + 1 }
              : item,
          ),
        }));
      },

      decreaseItem: (configurationKey) => {
        const currentItem = get().items.find(
          (item) =>
            (item.configurationKey ?? item.product.id) === configurationKey ||
            item.product.id === configurationKey,
        );

        if (!currentItem) {
          return;
        }

        if (currentItem.quantity <= 1) {
          get().removeItem(configurationKey);
          return;
        }

        set((state) => ({
          items: state.items.map((item) =>
            (item.configurationKey ?? item.product.id) === configurationKey ||
            item.product.id === configurationKey
              ? { ...item, quantity: item.quantity - 1 }
              : item,
          ),
        }));
      },

      setItemQuantity: (configurationKey, quantity) => {
        if (quantity <= 0) {
          get().removeItem(configurationKey);
          return;
        }

        set((state) => ({
          items: state.items.map((item) =>
            (item.configurationKey ?? item.product.id) === configurationKey ||
            item.product.id === configurationKey
              ? { ...item, quantity }
              : item,
          ),
        }));
      },

      clearCart: () => {
        set({
          items: [],
        });
      },

      clearAdItems: () => {
        set({
          adItems: [],
        });
      },

      getItemQuantity: (productId) => {
        return (
          get().items.find((item) => item.product.id === productId)?.quantity ??
          0
        );
      },

      getTotalItems: () => {
        return get().items.reduce((sum, item) => sum + item.quantity, 0);
      },

      getTotalAmount: () => {
        return get().items.reduce(
          (sum, item) =>
            sum +
            (item.configuredUnitPrice ?? item.product.price) * item.quantity,
          0,
        );
      },

      getTotalAdItems: () => {
        return get().adItems.length;
      },

      getTotalAdAmount: () => {
        return get().adItems.reduce((sum, item) => sum + item.ad.price, 0);
      },
    }),
    {
      name: 'dna-cart',
      storage: createJSONStorage(() => localStorage),
      partialize: (state) => ({
        items: state.items,
        adItems: state.adItems,
      }),
    },
  ),
);
import type { CartStoreItem } from '@/entities/cart';
import { FavouriteButton } from '@/entities/favourite';
import { formatPrice } from '@/shared/utils/format-price';
import { ProductQuantityCounter } from '@/widgets/ProductQuantityCounter';

import { calculateCartItemTotal } from '../../logic/calculate-cart-item-total';
import { CartItemCard } from '../CartItemCard/CartItemCard';

type CartProductItemCardProps = {
  item: CartStoreItem;
  onRemove: (configurationKey: string) => void;
};

export function CartProductItemCard({ item, onRemove }: CartProductItemCardProps) {
  const { product, quantity } = item;
  const image = product.images[0];
  const itemTotal = calculateCartItemTotal(item);
  const selectedById = new Map(
    (item.selectedAdditions ?? []).map((addition) => [
      addition.additionId,
      addition,
    ]),
  );
  const additionLines = (product.additions ?? []).flatMap((addition) => {
    const selected = selectedById.get(addition.id);
    if (!selected || selected.type !== addition.type) return [];
    if (
      addition.type === 'boolean' &&
      selected.type === 'boolean' &&
      !selected.value &&
      !addition.required
    ) return [];
    const total =
      addition.type === 'boolean'
        ? selected.value
          ? addition.price
          : 0
        : Number(selected.value) * addition.price;
    const value =
      addition.type === 'boolean'
        ? selected.value
          ? 'Да'
          : 'Нет'
        : `${selected.value} ${addition.unitLabel} × ${formatPrice(addition.price)}`;
    return [`${addition.title}: ${value}, ${total ? `+${formatPrice(total)}` : formatPrice(0)}`];
  });

  return (
    <CartItemCard
      href={`/market/product/${product.slug}`}
      imageUrl={image?.url}
      imageAlt={image?.alt ?? product.title}
      placeholderText="Нет изображения"
      title={product.title}
      category={
        <div className="space-y-1 text-sm text-muted-foreground">
          <p>{product.category.name}</p>
          {additionLines.map((line) => <p key={line}>{line}</p>)}
          {additionLines.length > 0 && (
            <p>Цена единицы: {formatPrice(item.configuredUnitPrice)}</p>
          )}
        </div>
      }
      price={<p className="text-base font-semibold sm:text-lg">{formatPrice(itemTotal)}</p>}
      priceMeta={`${quantity} × ${formatPrice(product.price)}`}
      actions={
        <div className="w-36 sm:w-40">
          <ProductQuantityCounter
            productId={item.configurationKey ?? product.id}
            variant="details"
          />
        </div>
      }
      favouriteButton={
        <FavouriteButton
          item={{ productId: product.id }}
          className="size-8 rounded-lg bg-muted hover:bg-muted/80"
        />
      }
      onRemove={() => onRemove(item.configurationKey ?? product.id)}
    />
  );
}
