export { CategoryPreviewGrid } from './CategoryPreviewGrid';

import type { CatalogCategory } from '@/shared/types/catalog-category';
import type { PlatformSectionId } from '@/shared/platform';

import { CategoryPreviewCard } from '../CategoryPreviewCard';

type CategoryPreviewGridProps = {
  section: PlatformSectionId;
  categories: CatalogCategory[];
  previewCategories: CatalogCategory[];
};

const GRID_CONFIG = {
  minCols: 2,
  maxCols: 6,
  smDivider: 2,
};

function getGridCols(count: number) {
  const { minCols, maxCols, smDivider } = GRID_CONFIG;

  const baseCols = Math.max(minCols, Math.min(count, maxCols));
  const smCols = Math.max(minCols, Math.ceil(baseCols / smDivider));

  return {
    base: minCols,
    sm: smCols,
    lg: baseCols,
  };
}

const gridColsClasses: Record<number, string> = {
  2: 'grid-cols-2',
  3: 'grid-cols-3',
  4: 'grid-cols-4',
  5: 'grid-cols-5',
  6: 'grid-cols-6',
};

const smGridColsClasses: Record<number, string> = {
  2: 'sm:grid-cols-2',
  3: 'sm:grid-cols-3',
  4: 'sm:grid-cols-4',
  5: 'sm:grid-cols-5',
  6: 'sm:grid-cols-6',
};

const lgGridColsClasses: Record<number, string> = {
  2: 'lg:grid-cols-2',
  3: 'lg:grid-cols-3',
  4: 'lg:grid-cols-4',
  5: 'lg:grid-cols-5',
  6: 'lg:grid-cols-6',
};

export function CategoryPreviewGrid({
  section,
  categories,
  previewCategories,
}: CategoryPreviewGridProps) {
  const cols = getGridCols(previewCategories.length);

  const gridClassName = [
    'grid gap-3',
    gridColsClasses[cols.base],
    smGridColsClasses[cols.sm],
    lgGridColsClasses[cols.lg],
  ].join(' ');

  return (
    <div className={gridClassName}>
      {previewCategories.map((category) => (
        <CategoryPreviewCard
          key={category.id}
          section={section}
          category={category}
          categories={categories}
        />
      ))}
    </div>
  );
}

import { useQuery } from '@tanstack/react-query';

import { getCatalogCategories } from '@/shared/catalog';
import {
  getPlatformCatalogHref,
  getPlatformSection,
  type PlatformSectionId,
} from '@/shared/platform';
import { SectionTitle } from '@/widgets/SectionTitle';

import { CategoryPreviewGrid } from './components/CategoryPreviewGrid';
import { getPreviewCategories } from './logic/get-preview-categories';

type CategoryPreviewProps = {
  section: PlatformSectionId;
  title?: string;
  limit?: number;
  emptyText?: string;
};

export function CategoryPreview({
  section,
  title,
  limit = 6,
  emptyText = 'Категории не найдены.',
}: CategoryPreviewProps) {
  const sectionConfig = getPlatformSection(section);

  const {
    data: categories,
    isLoading,
  } = useQuery({
    queryKey: ['categories', section],
    queryFn: () => getCatalogCategories({ section }),
  });

  const previewTitle = title ?? sectionConfig.categoryPreviewTitle;

  if (isLoading) {
    return (
      <section className="space-y-4">
        <SectionTitle title={previewTitle} level={2} />
        <p className="text-sm text-muted-foreground">Загружаем категории...</p>
      </section>
    );
  }

  const previewCategories = getPreviewCategories(categories ?? [], limit);

  return (
    <section className="space-y-4">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <SectionTitle
          title={previewTitle}
          href={getPlatformCatalogHref(section)}
          level={2}
        />
      </div>

      {previewCategories.length ? (
        <CategoryPreviewGrid
          section={section}
          categories={categories ?? []}
          previewCategories={previewCategories}
        />
      ) : (
        <div className="rounded-2xl border border-dashed border-border bg-card p-5 text-sm text-muted-foreground">
          {emptyText}
        </div>
      )}
    </section>
  );
}
