const products=load("rich_products");
const specialDescription=new Map([
 [10,['Клетки для кроликов.']],
 [11,['Деревянная клетка для кроликов.']],
 [18,['Трёхъярусная клетка для кроликов.']],
 [21,['Выгул оборудован полом.']],
 [24,['Модель с выносным гнездом и настилом в загоне.']],
 [36,['Двенадцатиместный комплекс в три яруса для содержания кроликов или кур.']],
 [39,['Компактный, но вместительный домик, рассчитанный на семь кур.']],
]);
const specialFeatures=new Map([
 [9,['Поставляется в полной комплектации.']],
 [20,['Окно и дверца выполнены из ПВХ.']],
 [24,[
  'Настил в загоне помогает сохранять птицу чистой и сухой, упрощает уборку и обеспечивает дополнительную защиту от хищников.',
  'Выносное утеплённое гнездо увеличивает полезную площадь домика, упрощает сбор яиц и защищает их от замерзания.',
 ]],
 [39,['Курятник оснащён электрикой и деревянным полом в загоне.']],
]);
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1).trim().replace(/\.$/,'')+'.'}
function match(text,re){const m=text.match(re);return m?.[1]?.trim()}
for(const [i,p] of products.entries()){
 const raw=p.description.blocks[0].text;
 const blocks=[];
 const descriptions=specialDescription.get(i);
 if(descriptions){
  blocks.push({type:'heading',text:'Описание'});
  for(const value of descriptions) blocks.push({type:'paragraph',text:value});
 }
 const dimension=match(raw,/Размер:\s*(\d+\s*×\s*\d+\s*×\s*\d+\s*см)/);
 if(dimension){
  blocks.push({type:'heading',text:'Размеры'});
  blocks.push({type:'paragraph',text:dimension+'.'});
 }
 const materials=[];
 const fieldDefs=[
  ['Каркас',/Каркас:\s*([^.]*)/],
  ['Внутренняя отделка',/Внутренняя отделка:\s*([^.]*)/],
  ['Наружная отделка',/Наружная отделка:\s*([^.]*)/],
  ['Кровля',/Кровля:\s*([^.]*)/],
  ['Сетка',/Сетка:\s*([^.]*)/],
  ['Окно',/Окно:\s*([^.]*)/],
  ['Крыша',/Крыша:\s*([^.]*)/],
 ];
 for(const [label,re] of fieldDefs){
  const value=match(raw,re);
  if(value) materials.push(`${label}: ${value.replace(/\.$/,'')}.`);
 }
 if(i===6) materials.push('Утеплитель: 50 мм.');
 if(i===39) materials.push('Крыша: двускатная.');
 if(materials.length){
  blocks.push({type:'heading',text:'Материалы и конструкция'});
  for(const value of materials) blocks.push({type:'paragraph',text:value});
 }
 const completion=match(raw,/Комплектация:\s*([^.]*)/);
 const features=[...(completion?[cap(completion)]:[]),...(specialFeatures.get(i)??[])];
 if(features.length){
  blocks.push({type:'heading',text:'Комплектация и особенности'});
  for(const value of features) blocks.push({type:'paragraph',text:value});
 }
 p.description={blocks};
}
store("segmented_products",products);
for(const [i,p] of products.entries()) text(`${i+1}: ${p.description.blocks.map(b=>`${b.type[0]}:${b.text}`).join(' | ')}`);

const products=load("segmented_products");
products[24].description.blocks=products[24].description.blocks.map(block=>block.text.startsWith('Наружная отделка:')?{...block,text:'Наружная отделка: имитация бруса 16 × 140 мм.'}:block);
store("segmented_products",products);
const current=await tools.exec_command({cmd:"sed -n '/^const PRODUCTION_PRODUCTS:/,/^type PreparedImage = {/p' api/prisma/seeds/production/seed.ts",workdir:"/Users/fedorshevchenko/Projects/work/dna",yield_time_ms:10000,max_output_tokens:50000});
let old=current.output.trimEnd();
old=old.replace(/
type PreparedImage = \{$/,'');
const replacement=`const PRODUCTION_PRODUCTS: SeedProduct[] = ${JSON.stringify(products,null,2)};`;
const patch=`*** Begin Patch
*** Update File: /Users/fedorshevchenko/Projects/work/dna/api/prisma/seeds/production/seed.ts
@@
-${old.split('
').join('
-')}
+${replacement.split('
').join('
+')}
*** End Patch`;
const result=await tools.apply_patch(patch);text(result)

