import { ContentDescription } from '@/components/ui/ContentDescription';
import type { Ad } from '@/entities/ad';
import { Gallery } from '@/widgets/Gallery';

import { AdDetailsActions } from './components/AdDetailsActions';
import { AdDetailsContacts } from './components/AdDetailsContacts';
import { AdDetailsInfo } from './components/AdDetailsInfo';

type AdDetailsProps = {
  ad: Ad;
};

export function AdDetails({ ad }: AdDetailsProps) {
  return (
    <article className="space-y-8 lg:space-y-10">
      <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1.4fr)_minmax(20rem,1fr)] lg:gap-10">
        <Gallery images={ad.images} title={ad.title} />

        <aside className="min-w-0 space-y-6 lg:sticky lg:top-6">
          <AdDetailsInfo ad={ad} />

          <section className="space-y-4 rounded-2xl border border-border bg-background p-4 sm:p-5">
            <AdDetailsContacts ad={ad} />
            <div className="border-t border-border pt-4">
              <AdDetailsActions ad={ad} />
            </div>
          </section>
        </aside>
      </div>

      <ContentDescription
        description={ad.description}
        className="max-w-3xl border-t border-border pt-6"
      />
