import { useState } from 'react';

import { ContentDescription } from '@/components/ui/ContentDescription';
import type { Product, SelectedProductAddition } from '@/entities/product';
import {
  calculateProductAdditionsTotal,
  createDefaultSelectedAdditions,
  validateSelectedProductAdditions,
} from '@/entities/product/lib/product-additions';
import { formatPrice } from '@/shared/utils/format-price';
import { Gallery } from '@/widgets/Gallery';

import { ProductAdditionsSelector } from './components/ProductAdditionsSelector/ProductAdditionsSelector';
import { ProductDetailsActions } from './components/ProductDetailsActions';
import { ProductDetailsInfo } from './components/ProductDetailsInfo';

type ProductDetailsProps = {
  product: Product;
};

export function ProductDetails({ product }: ProductDetailsProps) {
  const [selectedAdditions, setSelectedAdditions] = useState<
    SelectedProductAddition[]
  >(() => createDefaultSelectedAdditions(product.additions ?? []));
  const [showErrors, setShowErrors] = useState(false);
  const hasAdditions = (product.additions?.length ?? 0) > 0;
  const errors = validateSelectedProductAdditions(
    product.additions ?? [],
    selectedAdditions,
  );
  const configuredUnitPrice =
    product.price +
    calculateProductAdditionsTotal(product.additions ?? [], selectedAdditions);

  return (
    <article className="space-y-8 lg:space-y-10">
      <div className="grid items-start gap-6 lg:grid-cols-[minmax(0,1.4fr)_minmax(20rem,1fr)] lg:gap-10">
        <Gallery images={product.images} title={product.title} />

        <aside className="min-w-0 space-y-6 lg:sticky lg:top-6">
          <ProductDetailsInfo product={product} />

          <section className="space-y-5 rounded-2xl border border-border bg-background p-4 sm:p-5">
            <ProductAdditionsSelector
              additions={product.additions ?? []}
              selected={selectedAdditions}
              errors={showErrors ? errors : {}}
              onChange={setSelectedAdditions}
            />

            {hasAdditions && (
              <div className="flex items-baseline justify-between gap-4 border-t border-border pt-4">
                <span className="text-sm text-muted-foreground">
                  Итого за единицу
                </span>
                <span className="text-xl font-semibold">
                  {formatPrice(configuredUnitPrice)}
                </span>
              </div>
            )}

            <ProductDetailsActions
              product={product}
              selectedAdditions={selectedAdditions}
              isConfigurationValid={Object.keys(errors).length === 0}
              onInvalidConfiguration={() => setShowErrors(true)}
            />
          </section>
        </aside>
      </div>

      <ContentDescription
        description={product.description}
        className="max-w-3xl border-t border-border pt-6"
      />
    </article>
  );
}

